-- Verified project only: dkhwwvoplhfjccvjegty. All fixtures and helpers roll back.
-- Tests managed PostgreSQL/Auth trigger contracts; does not simulate HTTP signup.
-- Never writes Storage object metadata or bytes.
begin;
create temporary table uj_test_results(name text, status text) on commit drop;
grant insert,select on uj_test_results to anon,authenticated;
create function pg_temp.uj_assert(label text, ok boolean) returns void language plpgsql as $$
begin
 if ok is distinct from true then raise exception 'FAIL: %',label; end if;
 insert into uj_test_results values(label,'passed');
end $$;
create function pg_temp.uj_denied(label text, stmt text, expected text default '42501') returns void language plpgsql as $$
declare actual text;
begin
 begin execute stmt; exception when others then get stacked diagnostics actual=returned_sqlstate; end;
 perform pg_temp.uj_assert(label,actual=expected);
end $$;
select pg_temp.uj_assert('11 application tables all have RLS',(select count(*)=11 and bool_and(relrowsecurity) from pg_class where relnamespace='public'::regnamespace and relkind='r'));
select pg_temp.uj_assert('48 application and Storage policies',(select count(*)=48 from pg_policies where schemaname in ('public','storage')));
select pg_temp.uj_assert('all foreign keys have leading indexes',(not exists(select 1 from pg_constraint c where connamespace='public'::regnamespace and contype='f' and not exists(select 1 from pg_index i where i.indrelid=c.conrelid and i.indisvalid and i.indpred is null and not exists(select 1 from unnest(c.conkey) with ordinality k(att,pos) where i.indkey[(k.pos-1)::int] is distinct from k.att)))));
select pg_temp.uj_assert('spatial GiST index',(select indexdef like '%USING gist%' from pg_indexes where indexname='places_location_gist_idx'));
select pg_temp.uj_assert('two restricted private buckets',(select count(*)=2 and bool_and(not public and not ('image/svg+xml'=any(allowed_mime_types))) from storage.buckets));
select pg_temp.uj_assert('bucket size limits',(select bool_and(file_size_limit=case id when 'place-images' then 5242880 else 2097152 end) from storage.buckets));
select pg_temp.uj_assert('private helper search paths pinned',(select count(*)=4 and bool_and('search_path=""'=any(proconfig)) from pg_proc where pronamespace='unseen_private'::regnamespace));
select pg_temp.uj_assert('no public application RPC',(select count(*)=0 from pg_proc where pronamespace='public'::regnamespace));
select pg_temp.uj_assert('seven seeded categories',(select count(*)=7 from public.categories));
insert into auth.users(id,raw_user_meta_data) values ('00000000-0000-4000-8000-000000000001','{"full_name":"Rollback fixture","role":"admin"}'),('00000000-0000-4000-8000-000000000002','{}'),('00000000-0000-4000-8000-000000000003','{}');
select pg_temp.uj_assert('managed auth trigger creates profiles',(select count(*)=3 from public.profiles));
select pg_temp.uj_assert('role metadata cannot promote users',(select count(*)=3 and bool_and(role='user') from public.user_roles));
insert into public.user_roles(user_id,role) values('00000000-0000-4000-8000-000000000003','admin');
insert into public.places(id,slug,name,status,latitude,longitude,price_min_jod,price_max_jod) values('00000000-0000-4000-8000-000000000101','rollback-public','Rollback synthetic','published',31.95,35.91,0,10),('00000000-0000-4000-8000-000000000102','rollback-draft','Rollback synthetic draft','draft',null,null,null,null);
insert into public.place_categories(place_id,category_id) select p.id,c.id from public.places p cross join public.categories c where c.slug='nature';
insert into public.place_images(place_id,storage_path,alt_text,is_cover) values('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000101/test.jpg','Rollback image',true),('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000102/test.jpg','Rollback draft',true);
insert into public.user_preferences(user_id,available_minutes) values('00000000-0000-4000-8000-000000000001',120);
