insert into public.saved_places(user_id,place_id) values('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000101');
insert into public.recommendation_feedback(user_id,place_id,reaction) values('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000101','interested');
