reset role; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.uj_assert('other user cannot read profiles',(select count(*)= 1 from public.profiles));
select pg_temp.uj_assert('other user cannot read user_preferences',(select count(*)= 0 from public.user_preferences));
select pg_temp.uj_assert('other user cannot read user_preference_categories',(select count(*)= 0 from public.user_preference_categories));
