with changed as(update public.profiles set display_name='Intrusion' where id='00000000-0000-4000-8000-000000000001' returning *) select pg_temp.uj_assert('other user cannot update owner profile',(select count(*)=0 from changed));
with changed as(delete from public.user_preferences where user_id='00000000-0000-4000-8000-000000000001' returning *) select pg_temp.uj_assert('other user cannot delete user_preferences',(select count(*)=0 from changed));
with changed as(delete from public.user_preference_categories where user_id='00000000-0000-4000-8000-000000000001' returning *) select pg_temp.uj_assert('other user cannot delete user_preference_categories',(select count(*)=0 from changed));
with changed as(delete from public.saved_places where user_id='00000000-0000-4000-8000-000000000001' returning *) select pg_temp.uj_assert('other user cannot delete saved_places',(select count(*)=0 from changed));
with changed as(delete from public.recommendation_feedback where user_id='00000000-0000-4000-8000-000000000001' returning *) select pg_temp.uj_assert('other user cannot delete recommendation_feedback',(select count(*)=0 from changed));
select pg_temp.uj_denied('cross user preference insert','insert into public.user_preferences(user_id) values(''00000000-0000-4000-8000-000000000001'')','42501');
insert into public.user_preferences(user_id,available_minutes) values('00000000-0000-4000-8000-000000000002',60);
