select pg_temp.uj_denied('constraint image traversal','insert into public.place_images(place_id,storage_path,alt_text) values(''00000000-0000-4000-8000-000000000101'',''00000000-0000-4000-8000-000000000101/../wrong.jpg'',''Bad'')','23514');
