select pg_temp.uj_assert('generated point longitude/latitude',(select extensions.st_x(location::extensions.geometry)=35.91 and extensions.st_y(location::extensions.geometry)=31.95 from public.places where id='00000000-0000-4000-8000-000000000101'));
select pg_temp.uj_assert('meter distance and radius',(select extensions.st_distance(location,extensions.st_setsrid(extensions.st_makepoint(35.92,31.95),4326)::extensions.geography) between 900 and 1000 and extensions.st_dwithin(location,extensions.st_setsrid(extensions.st_makepoint(35.92,31.95),4326)::extensions.geography,1000) from public.places where id='00000000-0000-4000-8000-000000000101'));
